    static <T> T firstOf(List<?> items, Class<T> type) {
        for (Object o : items)
            if (type.isInstance(o)) return type.cast(o);
        return null;
    }
    public static void main(String[] args) {
        List<Object> mixed = List.of(1, "two", 3.0);
        String s = firstOf(mixed, String.class);
        System.out.println(s);
    }
}

